const $=s=>document.querySelector(s);
const S={role:'Student',screen:'login',tab:'home',admin:false,day:'Mon',inst:'Updates',busy:false,err:'',chat:null,pom:25*60,pomMax:25*60,pomRun:null,water:5,
 rem:{},done:{0:true},logout:false,manager:false,demoMode:false,managerOverview:null,managerMaterials:[],managerAssignments:[],managerQuizzes:[],managerStudents:[],studyMaterials:[],studyAssignments:[],studyQuizzes:[],studyNotifications:[],quizAnswers:[],activeQuiz:null,
 user:null,incomingRequests:[],outgoingRequests:[],availableUsers:[],serverFriends:[],threads:[],messages:[],adminOverview:null,adminUsers:[],activity:[],
 tasks:[{t:'Review linked list notes',s:'Data Structures · 45 min'},{t:'Solve matrix problems',s:'Linear Algebra · 30 min'}],
 posts:[{n:'Nadia Rahman',t:'Study group for Data Structures this week',l:12,liked:0,c:['Count me in!']},{n:'Rafi Islam',t:'Shared lecture notes for the quiz',l:5,liked:0,c:[]}],
 friends:{req:['Tasmia Noor'],sug:['Maya Sultana','Arif Hasan'],list:['Nadia Rahman'],sent:{}},
 notices:[{t:'Midterm routine published',s:'Official update · 2 hours ago',c:[]},{t:'Database class room changed',s:'CR notice · 1 day ago',c:[]}],
 files:[{t:'Data Structures - Linked Lists',s:'Lecture notes PDF · 2.4 MB'},{t:'Database Systems - ER diagrams',s:'Study guide PDF · 1.8 MB'}],
 pq:[{t:'Data Structures - Midterm 2024',s:'Uploaded by Dr. Rahman · answer key'},{t:'Discrete Mathematics - Final 2023',s:'Uploaded by Prof. Ahmed · 3 pages'}],
 groups:{'CSE 2023 - Section A':['Ayesha (CR): Class starts at 2:30 PM in Lab 3','Rafi: Will the room change affect us?'],'Data Structures Study Group':['Nadia: see you after class'],'Nadia Rahman':['Can you share the lecture notes?']},
 q:'',batch:'All',sel:null,adm:{low:true,wk:true}};
try{Object.assign(S,JSON.parse(localStorage.getItem('studymate-state')||'{}'));S.busy=false;S.pomRun=null}catch{}
S.screen='login';S.admin=false;S.user=null;S.role='Student';S.chatTarget=null;
let installPrompt=null;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;render()});
window.addEventListener('appinstalled',()=>{installPrompt=null;toast('StudyMate installed')});
const installApp=async()=>{if(!installPrompt)return toast('Use your browser menu to install StudyMate');installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;render()};
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
const DAYS=['Sat','Sun','Mon','Tue','Wed','Thu','Fri'];
const CL={Mon:[['Data Structures','09:00 AM','Room 302','Dr. Rahman'],['Discrete Mathematics','11:00 AM','Room 214','Prof. Ahmed'],['Database Systems','02:00 PM','Lab 04','Ms. Chowdhury']],Sun:[['Algorithms','10:00 AM','Room 210','Dr. Karim']],Tue:[['Linear Algebra','09:30 AM','Room 105','Prof. Ahmed']],Wed:[['Data Structures','09:00 AM','Room 302','Dr. Rahman']],Thu:[['Database Systems','11:00 AM','Lab 04','Ms. Chowdhury']]};
const STU=[['Nadia Rahman','CSE','2023',92,98],['Farhan Ahmed','CSE','2023',76,91],['Tasmia Noor','EEE','2024',48,72],['Rafi Islam','CSE','2024',64,84]];
const ini=n=>n.split(' ').map(x=>x[0]).join('').slice(0,2);
const toast=m=>{const t=$('#toast');t.textContent=m;t.className='show';setTimeout(()=>t.className='',1800)};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const apiBase=()=>{const saved=localStorage.getItem('studymate-api-url');if(saved)return saved.replace(/\/+$/,'');if(location.hostname==='localhost'&&location.port!=='3000')return 'http://localhost:3000';if(location.protocol==='capacitor:')return 'http://localhost:3000';return location.origin};
const api=async(path,options={})=>{const headers={'Content-Type':'application/json',...(options.headers||{})};const token=localStorage.getItem('studymate-token');if(token)headers.Authorization='Bearer '+token;let r;try{r=await fetch(apiBase()+path,{...options,headers})}catch{throw new Error('Cannot reach the StudyMate server. Check the server address and connection.')}const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||'Request failed.');return data};
let chatSocket=null;
const serverSettings=()=>modal(`<h3>Connect to StudyMate server</h3><small>Use your server URL (for example https://your-server.example).</small><input id="serverUrl" value="${esc(apiBase())}" placeholder="https://your-server.example"><button class="btn" onclick="saveServerUrl()">Save server</button><button class="btn o" onclick="close()">Cancel</button>`);
const saveServerUrl=()=>{const value=$('#serverUrl').value.trim().replace(/\/+$/,'');if(value){try{const u=new URL(value);if(!['http:','https:'].includes(u.protocol))throw 0}catch{return toast('Enter a valid http or https URL')}}if(value)localStorage.setItem('studymate-api-url',value);else localStorage.removeItem('studymate-api-url');location.reload()};
const modal=h=>{$('#modal').innerHTML='<div class="card">'+h+'</div>';$('#modal').className='show'};
const close=()=>$('#modal').className='';
const logoutNow=()=>{const token=localStorage.getItem('studymate-token');if(token)fetch(apiBase()+'/api/auth/logout',{method:'POST',headers:{Authorization:'Bearer '+token}}).catch(()=>{});localStorage.removeItem('studymate-token');if(chatSocket){chatSocket.close();chatSocket=null}clearInterval(S.pomRun);S.pomRun=null;S.busy=false;S.admin=false;S.manager=false;S.demoMode=false;S.user=null;S.err='';S.tab='home';S.screen='login';close();render()};
const logoutPrompt=()=>modal(`<h3>Log out?</h3><small>You will return to the login screen.</small><button class="btn d" onclick="logoutNow()">Log out</button><button class="btn o" onclick="close()">Cancel</button>`);
const go=(s,tab)=>{S.screen=s;if(tab)S.tab=tab;render();if(s==='friends')refreshFriends();if(s==='msgs')refreshThreads();if(s==='chat')refreshMessages();if(['adash','alist','areports','aset'].includes(s))refreshAdmin(s);if(['mdash','mmaterials','massignments','mquizzes','mprogress'].includes(s))refreshManager();if(['studyMaterials','studyAssignments','studyQuizzes','studyNotify'].includes(s))refreshStudy()};
const load=(fn,ms=700)=>{S.busy=true;render();setTimeout(()=>{S.busy=false;fn();render()},ms)};
const topBar=(t,back)=>`<div class="top">${back?`<button onclick="go('${back}')">←</button>`:''}${t}</div>`;
const nav=()=>`<div class="nav">${[['home','🏠','Home'],['routine','📅','Routine'],['planner','✅','Planner'],['progress','📊','Progress'],['profile','👤','Profile']].map(([k,i,l])=>`<button class="${S.tab==k?'on':''}" onclick="go('${k}','${k}')"><span>${i}</span>${l}</button>`).join('')}</div>`;
const anav=()=>`<div class="nav">${[['adash','🏠','Overview'],['alist','👥','Students'],['areports','📈','Reports'],['aset','⚙️','Settings']].map(([k,i,l])=>`<button class="${S.screen==k?'on':''}" onclick="go('${k}')"><span>${i}</span>${l}</button>`).join('')}</div>`;
const mnav=()=>`<div class="nav">${[['mdash','🏠','Home'],['mmaterials','📚','Materials'],['massignments','📝','Tasks'],['mquizzes','✅','Quizzes'],['mprogress','📊','Progress']].map(([k,i,l])=>`<button class="${S.screen==k?'on':''}" onclick="go('${k}')"><span>${i}</span>${l}</button>`).join('')}</div>`;
const sw=(on,fn)=>`<button class="sw ${on?'on':''}" onclick="${fn}"></button>`;
const item=(t,s,btn)=>`<div class="card row sp"><div class="av">${ini(t)}</div><div class="col"><h3>${t}</h3><small>${s}</small></div>${btn||''}</div>`;
const S_=[['home','Study goal'],];
const V={
login(){return `<div class="body" style="justify-content:center;gap:14px"><div style="text-align:center"><div class="av" style="width:64px;height:64px;margin:auto;font-size:28px;background:var(--p);color:#fff">S</div><h1 style="color:var(--t);margin-top:8px">StudyMate</h1><small>SMART STUDENT ASSISTANT · 3 ROLES</small></div><h3 style="margin-top:12px">${S.loginMode==='admin'?'Admin sign in':S.loginMode==='manager'?'Manager sign in':'Welcome back'}</h3><small>Sign in to your StudyMate account.</small>
<input id="em" type="email" autocomplete="username" value="${esc(S.authEmail||'')}" placeholder="Email address"><input id="pw" type="password" autocomplete="current-password" class="${S.err?'err':''}" placeholder="Password">${S.err?`<div class="error">${esc(S.err)}</div>`:''}
<button class="btn" onclick="login()">${S.busy?'<div class="spin"></div>':'Log in'}</button><div class="row"><button class="btn o" onclick="S.loginMode='admin';go('login')">🛡️ Admin</button><button class="btn o" onclick="S.loginMode='manager';go('login')">📘 Manager</button></div><button class="btn o" onclick="S.loginMode='student';go('register')">Create student account</button><button class="btn o" onclick="serverSettings()">Server: ${esc(apiBase())}</button><div class="card"><h3>Preview app screens offline</h3><small>Sample data only; no server or account needed.</small><div class="row" style="margin-top:10px"><button class="btn s o" onclick="openRoleDemo('student')">Student</button><button class="btn s o" onclick="openRoleDemo('manager')">Manager</button><button class="btn s o" onclick="openRoleDemo('admin')">Admin</button></div></div><small style="text-align:center">Online accounts and shared database features need a configured server.</small></div>`},
register(){const d=S.registerDraft||{};return topBar('Create account','login')+`<div class="body"><div class="card hero"><small>JOIN STUDYMATE</small><h3 style="color:#fff">Create your student account</h3><small>Your account will be saved in the StudyMate database.</small></div>${S.err?`<div class="error">${esc(S.err)}</div>`:''}<input id="rn" autocomplete="name" value="${esc(d.name||'')}" placeholder="Full name"><input id="re" type="email" autocomplete="email" value="${esc(d.email||'')}" placeholder="Email address"><input id="rd" value="${esc(d.department||'')}" placeholder="Department (e.g. CSE)"><input id="rb" value="${esc(d.batch||'')}" placeholder="Batch / year"><input id="rp" type="password" autocomplete="new-password" placeholder="Password (at least 8 characters)"><button class="btn" onclick="registerAccount()">${S.busy?'<div class="spin"></div>':'Create account'}</button><small>Registration creates a student account. Admin access is assigned separately.</small></div>`},
home(){const n=Object.keys(S.done).filter(k=>S.done[k]).length;return topBar('Good morning, '+esc(S.user?.name||'Student'))+`<div class="body">${installPrompt?'<button class="btn o" onclick="installApp()">⬇️ Install StudyMate</button>':''}<div class="card hero"><small>YOUR STUDY BUDDY</small><h3 style="color:#fff">Small steps today, big wins tomorrow.</h3><small>🔥 4-day study streak</small></div>
<div class="grid2">${[['📚','Materials','studyMaterials'],['📝','Assignments','studyAssignments'],['✅','Take quiz','studyQuizzes'],['🔔','Notifications','studyNotify'],['👥','Community','community'],['⏱️','Focus','pomo']].map(([i,l,s])=>`<div class="card tile" onclick="go('${s}')"><span>${i}</span>${l}</div>`).join('')}</div>
<h3>Today's classes</h3>${CL.Mon.slice(0,2).map((c,i)=>item(c[0],`${c[1]} · ${c[2]} · ${c[3]}`,i?'':'<span class="tag g">NOW</span>')).join('')}
<div class="card"><div class="row sp"><h3>Study goal</h3><small>2 of 4 hours · 50%</small></div><div class="bar"><i style="width:50%"></i></div></div>
<h3>Coming up</h3>${item('Database design project','Database Systems · due in 4 days')}
<div class="card"><div class="row sp"><h3>Water intake · ${S.water} of 8</h3></div><div class="row" style="margin-top:8px">${[...Array(8)].map((_,i)=>`<span onclick="S.water=${i+1};render()" style="font-size:22px;cursor:pointer;opacity:${i<S.water?1:.25}">💧</span>`).join('')}</div></div>
<div class="card" style="background:var(--pl)"><small>🤖 AI Suggestion</small><h3>Tomorrow: Data Structures</h3><small>Study Linked List for 1 hour today.</small></div></div>`+nav()},
routine(){const c=CL[S.day]||[];return topBar('Class routine')+`<div class="body"><div class="tabs">${DAYS.map(d=>`<button class="${S.day==d?'on':''}" onclick="S.day='${d}';render()">${d}</button>`).join('')}</div><small>${S.day} · ${c.length} classes</small>
${c.length?c.map((x,i)=>item(x[0],`${x[1]} · ${x[2]} · ${x[3]}`,sw(S.rem[S.day+i],`S.rem['${S.day+i}']=!S.rem['${S.day+i}'];toast(S.rem['${S.day+i}']?'Reminder on':'Reminder off');render()`))).join(''):'<div class="card" style="text-align:center"><span style="font-size:32px">🎉</span><h3>No classes</h3><small>Enjoy your free day!</small></div>'}</div>`+nav()},
planner(){return topBar('Your study plan')+`<div class="body"><div class="card hero row sp" onclick="go('pomo')"><div><small>POMODORO FOCUS</small><h3 style="color:#fff">25:00</h3></div><span class="tag">Start</span></div>
<h3>Today's tasks</h3>${S.tasks.length?S.tasks.map((t,i)=>`<div class="card row"><input type="checkbox" style="width:20px" ${S.done[i]?'checked':''} onchange="S.done[${i}]=this.checked;render()"><div class="col"><h3 style="${S.done[i]?'text-decoration:line-through;color:var(--m)':''}">${t.t}</h3><small>${t.s}</small></div></div>`).join(''):'<div class="card m">No tasks yet. Add one!</div>'}
<h3>Exam revision plan</h3>${item('Midterm revision','Data Structures · Week 5')}<h3>Assignment deadlines</h3>${item('Database design project','Due in 4 days')}
<button class="btn" onclick="modal('<h3>Add task</h3><input id=nt placeholder=\\'Task title\\'><input id=ns placeholder=\\'Subject · duration\\'><button class=\\'btn\\' onclick=\\'addTask()\\'>Add</button><button class=\\'btn o\\' onclick=\\'close()\\'>Cancel</button>')">+ Add task</button></div>`+nav()},
pomo(){const m=String(Math.floor(S.pom/60)).padStart(2,'0'),s=String(S.pom%60).padStart(2,'0');return topBar('Focus session','planner')+`<div class="body" style="justify-content:center"><small style="text-align:center">POMODORO FOCUS SESSION</small><div class="timer">${m}:${s}</div><div class="tabs" style="justify-content:center">${[25,50].map(x=>`<button class="${S.pomMax==x*60?'on':''}" onclick="setPom(${x})">${x} min</button>`).join('')}</div><button class="btn" onclick="togglePom()">${S.pomRun?'Pause':'Start'}</button><small style="text-align:center">Focus on one task at a time.</small></div>`},
ai(){return topBar('AI Study Assistant','home')+`<div class="body"><div class="card hero"><small>STUDY HELPER</small><h3 style="color:white">Ask a question about your study plan</h3><small>Classroom demo assistant</small></div><div class="card"><h3>Suggested questions</h3><div class="row" style="flex-wrap:wrap;margin-top:8px">${['How do I prepare for a quiz?','Explain a study routine','How can I focus?'].map(q=>`<button class="btn s o" onclick="askStudy('${q}')">${q}</button>`).join('')}</div></div><div class="card chat">${S.aiAnswer?`<div class="msg me">${esc(S.aiQuestion)}</div><div class="msg">${esc(S.aiAnswer)}</div>`:'<small>Ask for study tips, quiz preparation, or focus advice.</small>'}</div><div class="row"><input id="aiq" placeholder="Ask a study question"><button class="btn s" onclick="askStudy()">Ask</button></div></div>`+nav()},
progress(){const h=[2,3,2.5,4,3,1.5,1];return topBar('Weekly progress')+`<div class="body"><div class="card"><h3>Weekly study hours</h3><div class="chart" style="margin-top:10px">${h.map((v,i)=>`<div><i style="height:${v*24}px"></i>${'MTWTFSS'[i]}</div>`).join('')}</div></div>
<div class="card row"><div class="col"><h3>Class attendance</h3><small>Classes attended this semester</small></div><h2 style="color:var(--p)">92%</h2></div>
<div class="card row"><div class="ring" style="background:conic-gradient(var(--p) 75%,var(--pl) 0)"><b>75%</b></div><div><h3>Weekly goal</h3><small>15 of 20 study hours completed</small></div></div></div>`+nav()},
profile(){const u=S.user||{};return topBar('Profile and Settings')+`<div class="body"><div class="card row"><div class="av" style="width:56px;height:56px">${esc(ini(u.name||'Student'))}</div><div><h3>${esc(u.name||'Student')}</h3><small>${esc(u.department||'Student')} · Batch ${esc(u.batch||'—')} · ${esc(u.role||'Student')}</small><small style="display:block">${esc(u.email||'')}</small></div></div>
<div class="card"><div class="row sp"><div><h3>Online account</h3><small>Profile, friends and messages sync through the server database.</small></div></div><small style="display:block;margin-top:8px">Server: ${esc(apiBase())}</small><button class="btn s o" style="margin-top:8px" onclick="serverSettings()">Change server</button></div>
<div class="card"><h3>Notifications</h3>${[['Class reminders',1],['Assignment deadlines',1],['Weekly study summary',0]].map(([l,v],i)=>`<div class="row sp" style="margin-top:10px"><small style="font-size:13px;color:var(--t)">${l}</small>${sw(S['n'+i]??v,`S.n${i}=!(S.n${i}??${v});render()`)}</div>`).join('')}</div>
<button class="btn d" onclick="logoutPrompt()">Log out</button></div>`+nav()},
community(){return topBar('Community','home')+`<div class="body"><div class="row"><button class="btn s o" onclick="go('friends')">Friends</button><button class="btn s o" onclick="go('msgs')">Messages</button><button class="btn s o" onclick="go('inst')">Institution</button></div>
<button class="btn" onclick="modal('<h3>New post</h3><textarea id=np rows=3 placeholder=\\'Share an idea…\\'></textarea><button class=\\'btn\\' onclick=\\'addPost()\\'>Post</button><button class=\\'btn o\\' onclick=\\'close()\\'>Cancel</button>')">✏️ Create post</button>
${S.posts.map((p,i)=>`<div class="card"><div class="row"><div class="av">${ini(p.n)}</div><h3>${p.n}</h3></div><p style="margin:8px 0;font-size:14px">${p.t}</p>${p.c.map(c=>`<small style="display:block">💬 ${c}</small>`).join('')}<div class="row" style="margin-top:8px"><button class="btn s o" onclick="S.posts[${i}].liked=!S.posts[${i}].liked;S.posts[${i}].l+=S.posts[${i}].liked?1:-1;render()">${S.posts[i].liked?'❤️':'🤍'} ${p.l}</button><button class="btn s o" onclick="cmt('posts',${i})">Comment</button><button class="btn s o" onclick="openChat('${p.n}')">Message</button></div></div>`).join('')}</div>`+nav()},
friends(){const requests=S.incomingRequests.map(r=>`<div class="card row sp"><div class="av">${esc(ini(r.user.name))}</div><div class="col"><h3>${esc(r.user.name)}</h3><small>${esc(r.user.department||'Student')} · Batch ${esc(r.user.batch||'—')}</small></div><button class="btn s" onclick="answerFriendRequest(${r.id},'accept')">Accept</button><button class="btn s o" onclick="answerFriendRequest(${r.id},'reject')">Decline</button></div>`).join('')||'<div class="card m">No incoming requests.</div>';const people=S.availableUsers.map(u=>`<div class="card row sp"><div class="av">${esc(ini(u.name))}</div><div class="col"><h3>${esc(u.name)}</h3><small>${esc(u.department||'Student')} · Batch ${esc(u.batch||'—')}</small></div>${u.relationship==='friend'?'<span class="tag g">Friends</span>':u.relationship==='outgoing'?'<span class="tag">Request sent</span>':u.relationship==='incoming'?'<span class="tag">Incoming</span>':`<button class="btn s o" onclick="sendFriendRequest(${u.id})">Add</button>`}</div>`).join('')||'<div class="card m">No other students yet. Ask a classmate to create an account.</div>';const friends=S.serverFriends.map(f=>`<div class="card row sp"><div class="av">${esc(ini(f.name))}</div><div class="col"><h3>${esc(f.name)}</h3><small>${esc(f.department||'Student')} · Batch ${esc(f.batch||'—')}</small></div><button class="btn s o" data-name="${esc(f.name)}" onclick="openChat(${f.id},this.dataset.name)">Message</button></div>`).join('')||'<div class="card m">Accept a request to start a chat.</div>';return topBar('Friends','community')+`<div class="body"><div class="row sp"><h3>Friend requests</h3><button class="btn s o" onclick="refreshFriends()">Refresh</button></div>${requests}<h3>Find students</h3><input id="friendSearch" placeholder="Search by name or email" value="${esc(S.q)}" oninput="searchFriends(this.value)">${people}<h3>Your friends</h3>${friends}</div>`+nav()},
msgs(){const rows=S.serverFriends.map(f=>{const t=S.threads.find(x=>x.user.id===f.id);return `<div class="card row sp"><div class="av">${esc(ini(f.name))}</div><div class="col"><h3>${esc(f.name)}</h3><small>${esc(t?.lastMessage||'Start a conversation')}</small></div><button class="btn s o" data-name="${esc(f.name)}" onclick="openChat(${f.id},this.dataset.name)">Open</button></div>`}).join('')||'<div class="card m">Add and accept a friend before messaging.</div>';return topBar('Messages','community')+`<div class="body"><div class="row sp"><h3>Direct messages</h3><button class="btn s o" onclick="refreshThreads()">Refresh</button></div>${rows}<small>Messages are saved in the server database and delivered live while both users are online.</small></div>`+nav()},
chat(){const target=S.chatTarget||{id:0,name:'Chat'};const rows=S.messages.map(m=>`<div class="msg ${m.fromId===S.user?.id?'me':''}">${esc(m.text)}<small style="display:block;opacity:.7;margin-top:4px">${esc(m.createdAt)}</small></div>`).join('')||'<small>No messages yet. Say hello!</small>';return topBar(esc(target.name),'msgs')+`<div class="body"><div class="chat">${rows}</div><div class="row"><input id="mi" placeholder="Write a message..." onkeydown="if(event.key==='Enter')sendMessage()"><button class="btn s" onclick="sendMessage()">Send</button></div></div>`},
inst(){const k=S.inst,L={Updates:S.notices,Files:S.files,Questions:S.pq}[k];return topBar('Northstar University','home')+`<div class="body"><small>Computer Science Department · Official institution space · 248 students</small><div class="tabs">${['Updates','Files','Questions'].map(t=>`<button class="${k==t?'on':''}" onclick="S.inst='${t}';render()">${t}</button>`).join('')}</div>
${L.map((x,i)=>item(x.t,x.s,k=='Updates'?`<button class="btn s o" onclick="cmt('notices',${i})">Comment${x.c.length?' ('+x.c.length+')':''}</button>`:`<button class="btn s o" onclick="toast('${k=='Files'?'Downloading…':'Opening…'}')">${k=='Files'?'Download':'Open'}</button>`)).join('')}
${S.role=='Teacher'?`<button class="btn" onclick="go('upload')">⬆️ Upload resource / past question</button>`:''}${S.role=='CR/Captain'&&k=='Updates'?`<button class="btn" onclick="postNotice()">📢 Post notice</button>`:''}${S.role=='Student'?'<small style="text-align:center">Switch role in Profile to see Teacher / CR tools</small>':''}</div>`+nav()},
upload(){return topBar('Share course material','inst')+`<div class="body"><span class="tag" style="align-self:flex-start">TEACHER ACCESS · demo</span><select id="uc"><option>Data Structures</option><option>Discrete Mathematics</option><option>Database Systems</option></select><select id="ut"><option>Course notes / PDF</option><option>Past question</option></select><div class="drop" onclick="this.textContent='📄 lecture_notes.pdf selected';S.file=1">Tap to select PDF or document</div><button class="btn" onclick="doUpload()">${S.busy?'<div class="spin"></div>':'Publish to institution'}</button></div>`},
studyMaterials(){return topBar('Course materials','home')+`<div class="body"><div class="card hero"><small>STUDY LIBRARY</small><h3 style="color:white">Materials shared by your manager</h3></div>${S.studyMaterials.map(m=>item(m.title,`${m.course} · ${m.resourceType||'Notes'}${m.description?' · '+m.description:''}`,'<span class="tag g">Available</span>')).join('')||'<div class="card m">No materials have been published yet.</div>'}</div>`+nav()},
studyAssignments(){return topBar('Assignments','home')+`<div class="body"><small>Review the instructions, then submit your work before the due date.</small>${S.studyAssignments.map(a=>`<div class="card"><div class="row sp"><h3>${esc(a.title)}</h3><span class="tag">${esc(a.dueDate||'No due date')}</span></div><small>${esc(a.course)}</small><p class="small" style="margin-top:8px">${esc(a.instructions)}</p>${a.submission?`<div class="tag g" style="margin-top:8px">Submitted · ${esc(a.submission)}</div>`:`<button class="btn s" style="margin-top:10px" onclick="submitAssignment(${a.id})">Submit assignment</button>`}</div>`).join('')||'<div class="card m">No assignments posted yet.</div>'}</div>`+nav()},
studyQuizzes(){const q=S.activeQuiz;if(q){return topBar(q.title,'studyQuizzes')+`<div class="body"><small>${esc(q.course)} · ${q.questions.length} questions</small>${q.questions.map((x,i)=>`<div class="card"><h3>${i+1}. ${esc(x.prompt)}</h3>${x.options.map((o,j)=>`<label class="choice"><input type="radio" name="q${i}" ${Number(S.quizAnswers[i])===j?'checked':''} onchange="S.quizAnswers[${i}]=${j}"><span>${esc(o)}</span></label>`).join('')}</div>`).join('')}<button class="btn" onclick="submitQuiz()">Finish quiz</button></div>`+nav()}return topBar('Practice quizzes','home')+`<div class="body">${S.studyQuizzes.map(x=>`<div class="card"><h3>${esc(x.title)}</h3><small>${esc(x.course)} · ${x.questions.length} questions</small><button class="btn s" style="margin-top:10px" onclick="startQuiz(${x.id})">Take quiz</button></div>`).join('')||'<div class="card m">No quizzes published yet.</div>'}</div>`+nav()},
studyNotify(){return topBar('Study notifications','home')+`<div class="body">${S.studyNotifications.map(n=>`<div class="card"><h3>🔔 ${esc(n.title)}</h3><small>${esc(n.body)} · ${esc(n.manager)}</small><small style="display:block;margin-top:6px">${esc(n.createdAt)}</small></div>`).join('')||'<div class="card m">No new announcements.</div>'}</div>`+nav()},
mdash(){const c=S.managerOverview?.counts||{};return `<div class="demo">MANAGER WORKSPACE · COURSE TOOLS</div>`+topBar('Manager dashboard')+`<div class="body"><div class="card hero"><small>WELCOME, ${esc(S.user?.name||'MANAGER')}</small><h3 style="color:white">Manage learning materials and activities</h3><small>Publish resources, assignments, quizzes and announcements for students.</small></div><button class="btn s o" onclick="refreshManager()">Refresh manager data</button><div class="grid2">${[['Students',c.students],['Materials',c.materials],['Assignments',c.assignments],['Submissions',c.submissions],['Quizzes',c.quizzes],['Quiz attempts',c.quizAttempts]].map(([l,n])=>`<div class="card stat"><h2>${n??'—'}</h2><small>${l}</small></div>`).join('')}</div><button class="btn" onclick="managerNotification()">📢 Send student notification</button><button class="btn d" onclick="logoutNow()">Log out</button></div>`+mnav()},
mmaterials(){return topBar('Manage materials')+`<div class="body"><div class="card hero"><small>COURSE LIBRARY</small><h3 style="color:white">Materials for students</h3></div><button class="btn" onclick="addMaterial()">＋ Add course material</button>${S.managerMaterials.map(m=>item(m.title,`${m.course} · ${m.resource_type} · ${m.created_at}`)).join('')||'<div class="card m">No materials yet.</div>'}</div>`+mnav()},
massignments(){return topBar('Manage assignments')+`<div class="body"><div class="card hero"><small>STUDENT COURSEWORK</small><h3 style="color:white">Create and review assignments</h3></div><button class="btn" onclick="addAssignment()">＋ Create assignment</button>${S.managerAssignments.map(a=>`<div class="card"><div class="row sp"><h3>${esc(a.title)}</h3><span class="tag g">${a.submissions} submitted</span></div><small>${esc(a.course)} · Due ${esc(a.due_date||'No date')}</small><p class="small" style="margin-top:8px">${esc(a.instructions)}</p></div>`).join('')||'<div class="card m">No assignments yet.</div>'}</div>`+mnav()},
mquizzes(){return topBar('Manage quizzes')+`<div class="body"><div class="card hero"><small>QUIZ BUILDER</small><h3 style="color:white">Publish practice quizzes</h3></div><button class="btn" onclick="addQuiz()">＋ Create quiz</button>${S.managerQuizzes.map(q=>`<div class="card"><h3>${esc(q.title)}</h3><small>${esc(q.course)} · ${q.questions.length} questions</small></div>`).join('')||'<div class="card m">No quizzes yet.</div>'}</div>`+mnav()},
mprogress(){return topBar('Student progress')+`<div class="body"><div class="card hero"><small>CLASS OVERVIEW</small><h3 style="color:white">Assignments and quiz activity</h3></div>${S.managerStudents.map(s=>`<div class="card"><div class="row sp"><h3>${esc(s.name)}</h3><span class="tag">${esc(s.batch||'Student')}</span></div><small>${esc(s.email)} · ${esc(s.department||'')}</small><div class="row" style="margin-top:10px"><span class="tag g">${s.submissions} submissions</span><span class="tag">${s.quizAttempts} quiz attempts</span><span class="tag">${s.quizScore}/${s.quizTotal||0} points</span></div></div>`).join('')||'<div class="card m">Student activity will appear here.</div>'}</div>`+mnav()},
adash(){const c=S.adminOverview?.counts||{};const recent=S.adminOverview?.recentRegistrations||[];return `<div class="demo">ADMIN WORKSPACE · LIVE DATABASE</div>`+topBar('StudyMate admin')+`<div class="body"><button class="btn s o" onclick="refreshAdmin('adash')">Refresh database</button><div class="row" style="flex-wrap:wrap">${[['Student accounts',c.students??'—'],['Friendships',c.friendships??'—'],['Messages',c.messages??'—'],['Pending requests',c.pendingRequests??'—'],['New today',c.registrationsToday??'—']].map(a=>`<div class="card col" style="text-align:center;min-width:28%"><h2 style="color:var(--p)">${a[1]}</h2><small>${a[0]}</small></div>`).join('')}</div><h3>Recent registrations</h3>${recent.map(u=>`<div class="card"><h3>${esc(u.name)}</h3><small>${esc(u.email)} · ${esc(u.department||'No department')} · Batch ${esc(u.batch||'—')}</small><small style="display:block">Created ${esc(u.createdAt)}</small></div>`).join('')||'<div class="card m">No student accounts yet. Create a student account to begin.</div>'}<h3>User and course management</h3><button class="btn o" onclick="go('alist')">👥 Manage student accounts</button><button class="btn o" onclick="go('mmaterials')">📚 Manage course materials</button><button class="btn o" onclick="go('massignments')">📝 Manage assignments</button><button class="btn o" onclick="go('mquizzes')">✅ Manage quizzes</button><button class="btn o" onclick="go('areports')">📈 Reports and activity analysis</button><small>Private message text is not shown in the admin activity log.</small></div>`+anav()},
alist(){const l=S.adminUsers.filter(u=>!S.q||`${u.name} ${u.email} ${u.department} ${u.batch}`.toLowerCase().includes(S.q.toLowerCase()));return topBar('Registered students')+`<div class="body"><input id="sq" placeholder="Search accounts by name, email, batch" value="${esc(S.q)}" oninput="S.q=this.value;render(1)"><button class="btn s o" onclick="refreshAdmin('alist')">Refresh accounts</button>${l.map(u=>`<div class="card"><div class="row"><div class="av">${esc(ini(u.name))}</div><div class="col"><h3>${esc(u.name)}</h3><small>${esc(u.email)}</small></div><span class="tag">${esc(u.batch||'Student')}</span></div><small style="display:block;margin-top:8px">${esc(u.department||'No department')} · Joined ${esc(u.createdAt)}</small><small style="display:block">Last login: ${esc(u.lastLogin||'Never')} · Messages sent: ${u.sentMessages}</small></div>`).join('')||'<div class="card m">No student accounts found.</div>'}</div>`+anav()},
adetail(){const s=STU[S.sel??2];return topBar(s[0],'alist')+`<div class="body"><div class="card row"><div class="av" style="width:56px;height:56px">${ini(s[0])}</div><div><h3>${s[0]}</h3><small>${s[1]} · Batch ${s[2]}</small></div></div><div class="row">${[['Study goal',s[3]+'%'],['Attendance',s[4]+'%'],['Weekly hrs','16.5']].map(a=>`<div class="card col" style="text-align:center"><h3 style="color:${s[4]<75&&a[0]=='Attendance'?'var(--r)':'var(--p)'}">${a[1]}</h3><small>${a[0]}</small></div>`).join('')}</div>
<div class="card"><h3>Weekly study progress</h3><div class="chart" style="margin-top:10px">${[2,3,1,3,2,3,2].map((v,i)=>`<div><i style="height:${v*24}px"></i>${'MTWTFSS'[i]}</div>`).join('')}</div></div><h3>Subject progress</h3>${[['Data Structures',82],['Discrete Mathematics',68]].map(a=>`<div class="card"><div class="row sp"><h3>${a[0]}</h3><small>${a[1]}%</small></div><div class="bar"><i style="width:${a[1]}%"></i></div></div>`).join('')}</div>`+anav()},
areports(){const events=S.activity||[];return topBar('Account activity')+`<div class="body"><small>Account creation, logins, friend requests and message counts. Message contents stay private.</small><button class="btn s o" onclick="refreshAdmin('areports')">Refresh activity</button>${events.map(e=>`<div class="card"><h3>${esc(activityLabel(e.action))}</h3><small>${esc(e.actorName)}${e.targetName?' → '+esc(e.targetName):''}</small><small style="display:block;margin-top:5px">${esc(e.createdAt)}</small></div>`).join('')||'<div class="card m">No recorded activity yet.</div>'}</div>`+anav()},
aset(){return topBar('Admin settings')+`<div class="body"><div class="card"><h3>Low attendance alert threshold</h3><small>Alert when student attendance falls below this percentage.</small><input id="threshold" type="number" min="0" max="100" value="${S.adm.threshold??75}" onchange="S.adm.threshold=Number(this.value)"></div><div class="card"><div class="row sp"><div><h3>Weekly progress summary</h3><small>Every Monday</small></div>${sw(S.adm.wk,"S.adm.wk=!S.adm.wk;render()")}</div></div><button class="btn" onclick="saveAdminSettings()">Save system settings</button>
${item('Export student report','Download academic overview','<button class="btn s o" onclick="toast(&quot;Report exported (sample)&quot;)">Export</button>')}${item('Manage batches','Organize departments and cohorts','<button class="btn s o" onclick="toast(&quot;Opening batches (demo)&quot;)">Open</button>')}
<button class="btn d" onclick="logoutNow()">Log out</button></div>`+anav()}};
function render(keep){try{const copy={...S,busy:false,pomRun:null};localStorage.setItem('studymate-state',JSON.stringify(copy))}catch{}const v=V[S.screen]();const f=document.activeElement&&document.activeElement.id;$('#app').innerHTML=(S.demoMode?'<div class="demo">OFFLINE PREVIEW · SAMPLE DATA · NOT SYNCED</div>':'')+v;if(keep&&f){const e=$('#'+f);if(e){e.focus();if(e.setSelectionRange)e.setSelectionRange(1e3,1e3)}}}
const openRoleDemo=role=>{S.demoMode=true;S.admin=role==='admin';S.manager=role==='manager';S.role=role==='admin'?'Admin':role==='manager'?'Manager':'Student';S.user={id:role==='student'?101:role==='manager'?102:103,name:role==='student'?'Ayesha Rahman':role==='manager'?'Demo Manager':'Demo Admin',email:`${role}@demo.studymate.local`,department:'CSE',batch:'2023',role};S.managerMaterials=[{id:1,title:'Introduction to Data Structures',course:'Data Structures',resource_type:'Lecture notes',resourceType:'Lecture notes',created_at:'Today',description:'Arrays, stacks and linked lists.'}];S.managerAssignments=[{id:1,title:'Linked List Practice',course:'Data Structures',instructions:'Solve the linked-list exercises.',due_date:'2026-11-14',dueDate:'2026-11-14',submissions:2}];S.managerQuizzes=[{id:1,title:'Data Structures Quick Quiz',course:'Data Structures',questions:[{prompt:'Which structure follows LIFO?',options:['Queue','Stack','Tree'],answer:1}]}];S.managerStudents=[{name:'Ayesha Rahman',email:'ayesha@demo.studymate.local',department:'CSE',batch:'2023',submissions:1,quizAttempts:2,quizScore:4,quizTotal:5}];S.managerOverview={counts:{students:12,materials:8,assignments:4,submissions:9,quizzes:3,quizAttempts:18}};S.studyMaterials=[{id:1,title:'Introduction to Data Structures',course:'Data Structures',resourceType:'Lecture notes',description:'Arrays, stacks and linked lists.'}];S.studyAssignments=[{id:1,title:'Linked List Practice',course:'Data Structures',instructions:'Solve the linked-list exercises and explain your approach.',dueDate:'2026-11-14'}];S.studyQuizzes=[{id:1,title:'Data Structures Quick Quiz',course:'Data Structures',questions:[{prompt:'Which structure follows LIFO?',options:['Queue','Stack','Tree'],answer:1},{prompt:'Which operation adds an item to a queue?',options:['Enqueue','Pop','Peek'],answer:0}]}];S.studyNotifications=[{id:1,title:'Assignment reminder',body:'Linked List Practice is due this week.',manager:'Demo Manager',createdAt:'Today'}];S.adminOverview={counts:{students:12,friendships:7,messages:24,pendingRequests:2,registrationsToday:3},recentRegistrations:[{name:'Ayesha Rahman',email:'ayesha@demo.studymate.local',department:'CSE',batch:'2023',createdAt:'Today'}]};S.adminUsers=[{name:'Ayesha Rahman',email:'ayesha@demo.studymate.local',department:'CSE',batch:'2023',createdAt:'Today',lastLogin:'Today',sentMessages:4}];S.activity=[{action:'account_registered',actorName:'Ayesha Rahman',createdAt:'Today'},{action:'friend_request_sent',actorName:'Ayesha Rahman',targetName:'Rafi Islam',createdAt:'Yesterday'}];S.screen=role==='admin'?'adash':role==='manager'?'mdash':'home';S.tab=role==='student'?'home':'';S.err='';render()};
const authenticated=data=>{S.demoMode=false;localStorage.setItem('studymate-token',data.token);S.user=data.user;S.manager=data.user.role==='manager';S.admin=data.user.role==='admin';S.role=S.admin?'Admin':S.manager?'Manager':'Student';S.loginMode='student';S.err='';S.q='';S.tab=S.admin||S.manager?'':'home';S.screen=S.admin?'adash':S.manager?'mdash':'home';close();render();if(!S.admin&&!S.manager)startSocket();if(S.admin)refreshAdmin('adash');if(S.manager)refreshManager()};
const login=async()=>{const email=$('#em').value.trim();const password=$('#pw').value;if(!email||!password){S.err='Enter your email and password.';return render()}S.authEmail=email;S.busy=true;S.err='';render();try{authenticated(await api('/api/auth/login',{method:'POST',body:JSON.stringify({email,password})}))}catch(e){S.err=e.message;render()}finally{S.busy=false}};
const registerAccount=async()=>{const payload={name:$('#rn').value.trim(),email:$('#re').value.trim(),department:$('#rd').value.trim(),batch:$('#rb').value.trim(),password:$('#rp').value};S.registerDraft={name:payload.name,email:payload.email,department:payload.department,batch:payload.batch};S.busy=true;S.err='';render();try{authenticated(await api('/api/auth/register',{method:'POST',body:JSON.stringify(payload)}) )}catch(e){S.err=e.message;render()}finally{S.busy=false}};
const restoreSession=async()=>{if(!localStorage.getItem('studymate-token'))return;try{const data=await api('/api/auth/me');authenticated({token:localStorage.getItem('studymate-token'),user:data.user})}catch{localStorage.removeItem('studymate-token');S.user=null;S.err='Your session ended. Please sign in again.';render()}};
const startSocket=()=>{if(chatSocket&&chatSocket.readyState<=1)return;try{const u=new URL(apiBase());u.protocol=u.protocol==='https:'?'wss:':'ws:';u.pathname=u.pathname.replace(/\/$/,'')+'/api/ws';chatSocket=new WebSocket(u);chatSocket.onopen=()=>chatSocket.send(JSON.stringify({type:'auth',token:localStorage.getItem('studymate-token')}));chatSocket.onmessage=e=>{try{const packet=JSON.parse(e.data);if(packet.type==='message'){const m=packet.message;if(S.chatTarget&&((m.fromId===S.user?.id&&m.toId===S.chatTarget.id)||(m.toId===S.user?.id&&m.fromId===S.chatTarget.id))&&!S.messages.some(x=>x.id===m.id)){S.messages.push(m);if(S.screen==='chat')render()}if(S.screen==='msgs')refreshThreads()}}catch{}};chatSocket.onclose=()=>{chatSocket=null}}catch{chatSocket=null}};
const refreshFriends=async()=>{if(!S.user||S.admin)return;try{const [requests,friends,users]=await Promise.all([api('/api/friends/requests'),api('/api/friends'),api('/api/users?q='+encodeURIComponent(S.q||''))]);S.incomingRequests=requests.incoming;S.outgoingRequests=requests.outgoing;S.serverFriends=friends.friends;S.availableUsers=users.users;render(1)}catch(e){toast(e.message)}};
let friendSearchTimer=null;
const searchFriends=value=>{S.q=value;render(1);clearTimeout(friendSearchTimer);friendSearchTimer=setTimeout(refreshFriends,300)};
const sendFriendRequest=async userId=>{try{await api('/api/friends/requests',{method:'POST',body:JSON.stringify({userId})});toast('Friend request sent');await refreshFriends()}catch(e){toast(e.message)}};
const answerFriendRequest=async(id,decision)=>{try{await api(`/api/friends/requests/${id}/${decision}`,{method:'POST'});toast(decision==='accept'?'Friend added':'Request declined');await refreshFriends()}catch(e){toast(e.message)}};
const refreshThreads=async()=>{if(!S.user||S.admin)return;try{const [friends,threads]=await Promise.all([api('/api/friends'),api('/api/messages/threads')]);S.serverFriends=friends.friends;S.threads=threads.threads;render()}catch(e){toast(e.message)}};
const openChat=(id,name)=>{S.chatTarget={id:Number(id),name:String(name||'Student')};S.messages=[];S.screen='chat';render();startSocket();refreshMessages()};
const refreshMessages=async()=>{if(!S.chatTarget)return;try{const r=await api('/api/messages/'+S.chatTarget.id);S.messages=r.messages;render()}catch(e){toast(e.message);if(e.message.includes('sign in'))logoutNow()}};
const sendMessage=async()=>{const input=$('#mi');const text=input?.value.trim();if(!text||!S.chatTarget)return;input.disabled=true;try{const r=await api('/api/messages',{method:'POST',body:JSON.stringify({toUserId:S.chatTarget.id,text})});if(!S.messages.some(m=>m.id===r.message.id))S.messages.push(r.message);S.threads.sort((a,b)=>a.user.id===S.chatTarget.id?-1:b.user.id===S.chatTarget.id?1:0);render()}catch(e){toast(e.message);if(e.message.includes('sign in'))logoutNow()}finally{const field=$('#mi');if(field)field.disabled=false}};
const refreshAdmin=async view=>{if(!S.user||!S.admin||S.demoMode)return;try{if(view==='adash')S.adminOverview=await api('/api/admin/overview');if(view==='alist')S.adminUsers=(await api('/api/admin/users')).users;if(view==='areports')S.activity=(await api('/api/admin/activity')).events;if(view==='aset'){const r=await api('/api/admin/settings');S.adm.threshold=r.settings.attendanceThreshold;S.adm.wk=r.settings.weeklySummary}render()}catch(e){toast(e.message)}};
const saveAdminSettings=async()=>{if(S.demoMode){S.adm.threshold=Number($('#threshold')?.value||75);toast('Demo settings saved on this screen');return}try{const r=await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({attendanceThreshold:S.adm.threshold??75,weeklySummary:S.adm.wk??true})});S.adm.threshold=r.settings.attendanceThreshold;toast('Settings saved to database')}catch(e){toast(e.message)}};
const refreshManager=async()=>{if(!S.user||(!S.manager&&!S.admin)||S.demoMode)return;try{const [overview,materials,assignments,quizzes,students]=await Promise.all([api('/api/manager/overview'),api('/api/manager/materials'),api('/api/manager/assignments'),api('/api/manager/quizzes'),api('/api/manager/progress')]);S.managerOverview=overview;S.managerMaterials=materials.materials;S.managerAssignments=assignments.assignments;S.managerQuizzes=quizzes.quizzes;S.managerStudents=students.students;if(['mdash','mmaterials','massignments','mquizzes','mprogress'].includes(S.screen))render()}catch(e){toast(e.message)}};
const refreshStudy=async()=>{if(!S.user||S.manager||S.admin||S.demoMode)return;try{const [materials,assignments,quizzes,notifications]=await Promise.all([api('/api/materials'),api('/api/assignments'),api('/api/quizzes'),api('/api/study/notifications')]);S.studyMaterials=materials.materials;S.studyAssignments=assignments.assignments;S.studyQuizzes=quizzes.quizzes;S.studyNotifications=notifications.notifications;if(['studyMaterials','studyAssignments','studyQuizzes','studyNotify'].includes(S.screen))render()}catch(e){toast(e.message)}};
const addMaterial=()=>modal(`<h3>Publish course material</h3><input id="mt" placeholder="Material title"><input id="mc" value="Data Structures" placeholder="Course"><select id="mr"><option>Lecture notes</option><option>Past question</option><option>Study guide</option><option>Reference</option></select><textarea id="md" rows="3" placeholder="Description"></textarea><button class="btn" onclick="saveMaterial()">Publish material</button><button class="btn o" onclick="close()">Cancel</button>`);
const saveMaterial=async()=>{const data={title:$('#mt').value,course:$('#mc').value,resourceType:$('#mr').value,description:$('#md').value};if(S.demoMode){S.managerMaterials.unshift({...data,resource_type:data.resourceType,created_at:'Just now'});close();toast('Demo material published');render();return}try{await api('/api/manager/materials',{method:'POST',body:JSON.stringify(data)});close();toast('Material published');await refreshManager()}catch(e){toast(e.message)}};
const addAssignment=()=>modal(`<h3>Create assignment</h3><input id="at" placeholder="Assignment title"><input id="ac" value="Data Structures" placeholder="Course"><textarea id="ai" rows="3" placeholder="Instructions"></textarea><input id="ad" type="date"><button class="btn" onclick="saveAssignment()">Publish assignment</button><button class="btn o" onclick="close()">Cancel</button>`);
const saveAssignment=async()=>{const data={title:$('#at').value,course:$('#ac').value,instructions:$('#ai').value,dueDate:$('#ad').value};if(S.demoMode){S.managerAssignments.unshift({...data,id:Date.now(),due_date:data.dueDate,submissions:0});S.studyAssignments.unshift({...data,id:Date.now()});close();toast('Demo assignment published');render();return}try{await api('/api/manager/assignments',{method:'POST',body:JSON.stringify(data)});close();toast('Assignment published');await refreshManager()}catch(e){toast(e.message)}};
const addQuiz=()=>modal(`<h3>Create quiz</h3><input id="qt" placeholder="Quiz title"><input id="qc" value="Data Structures" placeholder="Course"><input id="qp" placeholder="Question"><input id="q0" placeholder="Option 1"><input id="q1" placeholder="Option 2"><input id="q2" placeholder="Option 3 (optional)"><select id="qa"><option value="0">Correct answer: Option 1</option><option value="1">Correct answer: Option 2</option><option value="2">Correct answer: Option 3</option></select><button class="btn" onclick="saveQuiz()">Publish quiz</button><button class="btn o" onclick="close()">Cancel</button>`);
const saveQuiz=async()=>{const options=[$('#q0').value,$('#q1').value,$('#q2').value].filter(Boolean),data={title:$('#qt').value,course:$('#qc').value,questions:[{prompt:$('#qp').value,options,answer:Number($('#qa').value)}]};if(S.demoMode){S.managerQuizzes.unshift({...data,id:Date.now()});S.studyQuizzes.unshift({...data,id:Date.now()});close();toast('Demo quiz published');render();return}try{await api('/api/manager/quizzes',{method:'POST',body:JSON.stringify(data)});close();toast('Quiz published');await refreshManager()}catch(e){toast(e.message)}};
const managerNotification=()=>modal(`<h3>Notify students</h3><input id="ntitle" placeholder="Notification title"><textarea id="nbody" rows="3" placeholder="Announcement"></textarea><button class="btn" onclick="sendStudyNotification()">Send announcement</button><button class="btn o" onclick="close()">Cancel</button>`);
const sendStudyNotification=async()=>{const data={title:$('#ntitle').value,body:$('#nbody').value};if(S.demoMode){S.studyNotifications.unshift({...data,manager:'Demo Manager',createdAt:'Just now'});close();toast('Demo announcement sent');render();return}try{await api('/api/manager/notifications',{method:'POST',body:JSON.stringify(data)});close();toast('Students notified');await refreshManager()}catch(e){toast(e.message)}};
const submitAssignment=id=>modal(`<h3>Submit assignment</h3><small>Your response will be saved to the coursework database.</small><textarea id="submission" rows="7" placeholder="Type or paste your response"></textarea><button class="btn" onclick="saveSubmission(${Number(id)})">Submit work</button><button class="btn o" onclick="close()">Cancel</button>`);
const saveSubmission=async id=>{if(S.demoMode){const a=S.studyAssignments.find(x=>x.id===id);if(a)a.submission=$('#submission').value;close();toast('Demo assignment submitted');render();return}try{await api(`/api/assignments/${id}/submit`,{method:'POST',body:JSON.stringify({response:$('#submission').value})});close();toast('Assignment submitted');await refreshStudy()}catch(e){toast(e.message)}};
const startQuiz=id=>{S.activeQuiz=S.studyQuizzes.find(q=>q.id===id);S.quizAnswers=Array(S.activeQuiz?.questions.length||0).fill(null);render()};
const submitQuiz=async()=>{if(S.quizAnswers.some(a=>a===null))return toast('Answer each question first');if(S.demoMode){const score=S.activeQuiz.questions.reduce((n,q,i)=>n+(q.answer===S.quizAnswers[i]?1:0),0),total=S.activeQuiz.questions.length;S.activeQuiz=null;S.quizAnswers=[];toast(`Demo quiz result: ${score}/${total}`);render();return}try{const r=await api(`/api/quizzes/${S.activeQuiz.id}/attempt`,{method:'POST',body:JSON.stringify({answers:S.quizAnswers})});S.activeQuiz=null;S.quizAnswers=[];toast(`Quiz result: ${r.score}/${r.total}`);await refreshStudy()}catch(e){toast(e.message)}};
const askStudy=question=>{const text=question||$('#aiq')?.value.trim();if(!text)return toast('Type a study question');S.aiQuestion=text;const q=text.toLowerCase();S.aiAnswer=q.includes('quiz')?'Review the course materials, make a short revision list, then take a practice quiz. Check missed answers and revisit those topics.':q.includes('focus')?'Choose one small task, set the 25-minute focus timer, silence distractions and take a short break when it ends.':q.includes('routine')?'Plan short study blocks around your class routine. Start with the nearest deadline and leave a review block before each quiz.':'Break the topic into small parts, review the course notes, practise one example, and add the next study block to your planner. This assistant uses built-in demo guidance.';render()};
const activityLabel=a=>({account_registered:'Student account created',login:'Signed in',logout:'Signed out',friend_request_sent:'Friend request sent',friend_request_accepted:'Friend request accepted',friend_request_rejected:'Friend request declined',message_sent:'Message sent (content hidden)',admin_seeded:'Admin account initialized'}[a]||a);
const addTask=()=>{const t=$('#nt').value.trim();if(!t)return toast('Enter a title');S.tasks.push({t,s:$('#ns').value||'General'});close();toast('Task added');render()};
const addPost=()=>{const t=$('#np').value.trim();if(!t)return toast('Write something first');S.posts.unshift({n:'Alex Morgan',t,l:0,liked:0,c:[]});close();toast('Posted');render()};
const cmt=(k,i)=>modal(`<h3>Comments</h3>${S[k][i].c.map(c=>`<small>💬 ${c}</small>`).join('')||'<small>No comments yet</small>'}<input id="ci" placeholder="Add a comment"><button class="btn" onclick="S['${k}'][${i}].c.push($('#ci').value||'👍');close();toast('Comment added');render()">Send</button><button class="btn o" onclick="close()">Close</button>`);
const f_acc=n=>{S.friends.req=S.friends.req.filter(x=>x!=n);S.friends.list.push(n);toast('Friend added');render()};
const postNotice=()=>modal(`<h3>Post notice</h3><select><option>CSE 2023 - Section A</option><option>All CSE students</option></select><textarea id="nn" rows=3 placeholder="Notice text"></textarea><button class="btn" onclick="const t=$('#nn').value.trim();if(!t)return toast('Write a notice');S.notices.unshift({t,s:'CR notice · just now',c:[]});close();toast('Notice sent');render()">Send</button><button class="btn o" onclick="close()">Cancel</button>`);
const doUpload=()=>{if(!S.file)return toast('Select a file first');const k=$('#ut').value.startsWith('Past');load(()=>{(k?S.pq:S.files).unshift({t:$('#uc').value+(k?' - Past question':' - New notes'),s:'Uploaded by you · just now'});S.file=0;S.inst=k?'Questions':'Files';toast('Uploaded successfully');S.screen='inst'},900)};
const setPom=x=>{clearInterval(S.pomRun);S.pomRun=null;S.pomMax=S.pom=x*60;render()};
const togglePom=()=>{if(S.pomRun){clearInterval(S.pomRun);S.pomRun=null}else S.pomRun=setInterval(()=>{if(--S.pom<=0){clearInterval(S.pomRun);S.pomRun=null;S.pom=S.pomMax;toast('Session complete! 🎉')}if(S.screen=='pomo')render()},1000);render()};
render();
restoreSession();
